package com.ambica.tests;

import org.openqa.selenium.By;
import org.openqa.selenium.WebDriver;
import org.openqa.selenium.WebElement;
import org.openqa.selenium.chrome.ChromeDriver;
import org.testng.Assert;
import org.testng.annotations.Test;

public class ProductionCapacityTest {
    @Test
    public void testProductionCapacityUpdate() {
        WebDriver driver = new ChromeDriver();
        driver.get("https://gc-dev.centralindia.cloudapp.azure.com/ambica/master-data/production-capacity");

        driver.findElement(By.xpath("//button[contains(text(),'Master Data')]")).click();
        driver.findElement(By.xpath("//a[contains(text(),'Production Capacity')]")).click();

        WebElement searchBox = driver.findElement(By.cssSelector("input[placeholder='Search by width/category']"));
        searchBox.sendKeys("Width 23");

        WebElement capacityInput = driver.findElement(By.cssSelector("input[placeholder='-']"));
        capacityInput.clear();
        capacityInput.sendKeys("23232");

        driver.findElement(By.xpath("//button[contains(text(),'Save')]")).click();
        driver.findElement(By.xpath("//button[contains(text(),'Refresh')]")).click();

        Assert.assertEquals(capacityInput.getAttribute("value"), "23232");
        driver.quit();
    }
}
